
/**
 * 更新galaxy查询模板中 app_label为app_id
 */
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT     common_app_label AS app_id,  SUM(common_sessions) as sessions,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets,     SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM     tsg_base_metrics WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND notEmpty(common_app_label) GROUP BY  common_app_label ORDER BY     ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 8;
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT1M\',\'zero\') AS stat_time,common_app_label AS app_id,ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG(common_establish_latency_ms) DESC LIMIT 10 ) GROUP BY stat_time,common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 29;
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT1M\',\'zero\') AS stat_time,common_app_label AS app_id,ROUND(AVG(http_response_latency_ms)) AS http_response_latency FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG(http_response_latency_ms) DESC LIMIT 10) GROUP BY stat_time,common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 30;
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT1M\',\'zero\') AS stat_time,common_app_label AS app_id,ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG(ssl_con_latency_ms) DESC LIMIT 10 ) GROUP BY stat_time,common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 31;
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT1M\',\'zero\') AS stat_time,common_app_label AS app_id,ROUND(AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)),4) AS sequence_gap_loss_percent FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN (SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)) DESC LIMIT 10 ) GROUP BY stat_time,common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 32;
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT1M\',\'zero\') AS stat_time, common_app_label AS app_id, ROUND(AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)),4) AS pkt_retrans_percent FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label IN ( SELECT common_app_label FROM tsg_base_metrics WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) GROUP BY common_app_label ORDER BY AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)) DESC LIMIT 10 ) GROUP BY stat_time, common_app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 33;
UPDATE `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT     anyLast(common_app_label) AS app_id, anyLast(app_category) AS app_category, anyLast(app_subcategory) AS app_subcategory, anyLast(app_risk) AS app_risk, count(distinct(common_client_ip)) AS count FROM     tsg_base_metrics WHERE     common_app_label = \'${parameter.appId?js_string}\' \",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' WHERE `id` = 50;
